insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-1', 'road-to-selling', null, null, 'What else has to be true before Quiver ships in the US?', 'On the call Thomas named the blockers: FAA approval to sell, the foam case inserts (waiting on a CNC router), obstacle avoidance, and the GPS interference. He wants the last two resolved before units ship. Is anything missing from that list?', 'question', 'technical', 'selling', 'Dev Kit', 'thomas', '{"kind":"call","ref":"sep29-3","label":"Sep 29 call"}'::jsonb, '2026-09-29T11:30:00-05:00', '2026-09-29T11:30:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-2', 'road-to-selling', null, null, 'Make sales the Quiver focus for the coming months', 'Quiver has cost a lot to build and needs to earn revenue. Once the blockers are cleared, the project shifts from design and engineering to selling as many units as it can.', 'proposal', 'technical', 'selling', 'Dev Kit', 'thomas', '{"kind":"call","ref":"sep29-4","label":"Sep 29 call"}'::jsonb, '2026-09-29T11:30:00-05:00', '2026-09-29T11:30:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-2-p1', 'Q-2', null, 'Make sales the focus of the Quiver project for the coming months.', 'thomas', '{"kind":"call","ref":"sep29-4","label":"Sep 29 call"}'::jsonb, 0, '2026-09-29T11:30:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-3', 'gps-rf', null, null, 'GPS interference: move the GPS, shield the switches, or revise the PCB?', 'The M9N loses satellites with the two Ethernet switches installed, on the Houston unit and the West Texas unit (T-13). Erick is learning the spectrum analyzer to confirm the switches are the source, and Julius is flying the Ethernet build this week. Thomas wants this fixed before units ship.', 'question', 'technical', 'gps', 'Dev Kit v1.1', 'thomas', '{"kind":"call","ref":"sep29-10","label":"Sep 29 call"}'::jsonb, '2026-09-29T11:30:00-05:00', '2026-09-29T11:30:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-3-p1', 'Q-3', null, 'Give the M9N a longer cable and mount it somewhere else, with an updated cradle. A PCB update would be more pain than anything.', 'erick', '{"kind":"call","ref":"sep29-10","label":"Sep 29 call"}'::jsonb, 0, '2026-09-29T11:30:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-3-p2', 'Q-3', null, 'If the spectrum analyzer shows the switches are the source, shield them and add standoffs. Keep the modifications as small as possible.', 'erick', '{"kind":"call","ref":"sep29-10","label":"Sep 29 call"}'::jsonb, 1, '2026-09-29T11:30:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-3-p3', 'Q-3', null, 'If the fix needs a PCB revision, start it sooner rather than later.', 'thomas', '{"kind":"call","ref":"sep29-10","label":"Sep 29 call"}'::jsonb, 2, '2026-09-29T11:30:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-4', 'gps-rf', '3250', null, 'Primary GPS: offer the Here4 and the Holybro NEO-F9P, retire the Wren Mini', 'PR #267 adds the CubePilot Here4 and the Holybro H-RTK NEO-F9P Rover as primary GPS options in the CAD and the BOM, and retires the Wren Mini. It is a draft, stacked on the mechanical sync in PR #266.', 'proposal', 'technical', 'gps', 'Dev Kit v1.1', 'thomas', '{"kind":"pr","ref":"267","label":"PR #267","url":"https://github.com/Arrow-air/project-quiver/pull/267"}'::jsonb, '2026-09-18T23:09:00-05:00', '2026-09-18T23:09:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-4-p1', 'Q-4', null, 'Support both the Here4 and the NEO-F9P Rover as primary GPS alternatives. The Wren Mini is retired, not a third option.', 'thomas', '{"kind":"pr","ref":"267","label":"PR #267","url":"https://github.com/Arrow-air/project-quiver/pull/267"}'::jsonb, 0, '2026-09-18T23:09:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-5', 'interface', '3331', null, 'Attachment power: the 12 V payload rail is about 13 W, shared by three ports', 'The attachment interface is sized for logic-level payloads. Floodlights, spreaders, larger gimbals and heaters want 20 to 100 W or more, so each one grows its own battery pigtail today (#233). The issue asks for a direction for the next main PCB and attach PCB revision.', 'question', 'technical', 'payload', 'Dev Kit v1.1', null, '{"kind":"issue","ref":"234","label":"#234","url":"https://github.com/Arrow-air/project-quiver/issues/234"}'::jsonb, '2026-07-09T21:38:00-05:00', '2026-07-09T21:38:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-5-p1', 'Q-5', null, 'A dedicated payload 12 V system: a separate converter sized for payloads (100 W class), with per-port switching and fusing.', null, '{"kind":"issue","ref":"234","label":"#234","url":"https://github.com/Arrow-air/project-quiver/issues/234"}'::jsonb, 0, '2026-07-09T21:38:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-5-p2', 'Q-5', null, 'Expose switched, fused battery voltage on the attachment interface and let attachments regulate locally. Needs a pogo contact current check and a hot-mate arcing plan.', null, '{"kind":"issue","ref":"234","label":"#234","url":"https://github.com/Arrow-air/project-quiver/issues/234"}'::jsonb, 1, '2026-07-09T21:38:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-5-p3', 'Q-5', null, 'No board change: publish one blessed high-power pigtail pattern (connector, fuse, switch).', null, '{"kind":"issue","ref":"234","label":"#234","url":"https://github.com/Arrow-air/project-quiver/issues/234"}'::jsonb, 2, '2026-07-09T21:38:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-6', 'parameters', null, null, 'Battery failsafe: approve the BMS capacity values?', 'T-01 proposes triggering the battery failsafe from the pack''s BMS count instead of ESC voltage: warn at 7,500 mAh left (25 percent), land at 4,500 mAh left (15 percent). Julius owns the battery PCB and the pack integration, so it is his call to check. A no comes with the number he would use instead.', 'question', 'technical', 'battery', 'Dev Kit', null, '{"kind":"issue","ref":"248","label":"#248","url":"https://github.com/Arrow-air/project-quiver/issues/248"}'::jsonb, '2026-09-09T15:59:00-05:00', '2026-09-29T11:30:00-05:00', '{"positionId":"p1","byId":"erick","at":"2026-09-30T02:00:00-05:00","override":false,"decision":"D-001","source":{"kind":"issue","ref":"248","label":"#248","url":"https://github.com/Arrow-air/project-quiver/issues/248"},"note":"Accepted on GitHub: BATT2_LOW_MAH 7500 and BATT2_CRT_MAH 4500, documented in Pilot''s Handbook §4.2.1 and Initial Configuration Guide §7.3 and §7.4."}'::jsonb, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-6-p1', 'Q-6', null, 'Yes: BATT2_LOW_MAH 7500 and BATT2_CRT_MAH 4500 go into the next parameter card, and the Handbook and the guide drop their "proposed" marker.', null, '{"kind":"issue","ref":"248","label":"#248","url":"https://github.com/Arrow-air/project-quiver/issues/248"}'::jsonb, 0, '2026-09-09T15:59:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-6-r1', 'Q-6', 'Q-6-p1', 'Asked Julius on the call for his input on the cutoffs, now that the Tattu BMS is available.', 'erick', '{"kind":"call","ref":"sep29-15","label":"Sep 29 call"}'::jsonb, 0, '2026-09-29T11:30:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-6-r2', 'Q-6', 'Q-6-p1', 'I will write something on GitHub.', 'julius', '{"kind":"call","ref":"sep29-15","label":"Sep 29 call"}'::jsonb, 0, '2026-09-29T11:30:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-6-r3', 'Q-6', 'Q-6-p1', 'Q1: Yes. The proposed low and critical values are good. Side note: for manual flights, LAND_REPOSITION should stay enabled, so the pilot can steer away from a bad spot if a failsafe landing triggers.', 'julius', '{"kind":"issue","ref":"248","label":"#248","url":"https://github.com/Arrow-air/project-quiver/issues/248"}'::jsonb, 0, '2026-09-30T01:07:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-7', 'parameters', null, null, 'Refuse to arm below 30 percent remaining?', 'The second T-01 question, judged on its own. BATT2_ARM_MAH 9000 would refuse arming with less than 30 percent left. Because the BMS count persists across boots, a pack installed half used would be caught. The lead has not adopted it yet.', 'question', 'technical', 'battery', 'Dev Kit', null, '{"kind":"issue","ref":"248","label":"#248","url":"https://github.com/Arrow-air/project-quiver/issues/248"}'::jsonb, '2026-09-09T15:59:00-05:00', '2026-09-09T15:59:00-05:00', '{"positionId":"p1","byId":"erick","at":"2026-09-30T02:00:00-05:00","override":false,"decision":"D-002","source":{"kind":"issue","ref":"248","label":"#248","url":"https://github.com/Arrow-air/project-quiver/issues/248"},"note":"Accepted on GitHub: BATT2_ARM_MAH 9000 added, and LAND_REPOSITION stays 1."}'::jsonb, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-7-p1', 'Q-7', null, 'Yes: add BATT2_ARM_MAH 9000 to the same parameter card revision.', null, '{"kind":"issue","ref":"248","label":"#248","url":"https://github.com/Arrow-air/project-quiver/issues/248"}'::jsonb, 0, '2026-09-09T15:59:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-7-r1', 'Q-7', 'Q-7-p1', 'Q2: Yes. The arming block at 9000 mAh makes sense.', 'julius', '{"kind":"issue","ref":"248","label":"#248","url":"https://github.com/Arrow-air/project-quiver/issues/248"}'::jsonb, 0, '2026-09-30T01:07:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-8', 'where-we-sell', null, null, 'Where do we sell Quiver: the Arrow store, a local page, or both?', 'Thomas will sell locally through his business out here, and wonders whether that should run through the Arrow store or a landing page tailored to what customers here care about. Either way the sale runs through the Arrow store process and pays back to the DAO. What is learned selling in Texas should carry over to other manufacturers selling elsewhere.', 'question', 'technical', 'sales', 'Dev Kit', 'thomas', '{"kind":"call","ref":"sep29-5","label":"Sep 29 call"}'::jsonb, '2026-09-29T11:30:00-05:00', '2026-09-29T11:30:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-8-p1', 'Q-8', null, 'Both: a page tailored to local customers, and the Arrow store running a standard online sales funnel.', 'thomas', '{"kind":"call","ref":"sep29-5","label":"Sep 29 call"}'::jsonb, 0, '2026-09-29T11:30:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-8-r1', 'Q-8', 'Q-8-p1', 'It would not hurt to have two sales pages: one for the DAO that we advertise, and one Thomas uses locally. This needs input from the whole DAO.', 'erick', '{"kind":"call","ref":"sep29-5","label":"Sep 29 call"}'::jsonb, 0, '2026-09-29T11:30:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-9', 'who-we-sell-to', null, null, 'Aim the online funnel at integrators, attachment developers and dev-kit buyers', 'There is a lot of wisdom in running a good online sales funnel. Thomas suggests pointing it at the people who would build on Quiver.', 'proposal', 'technical', 'sales', 'Dev Kit', 'thomas', '{"kind":"call","ref":"sep29-6","label":"Sep 29 call"}'::jsonb, '2026-09-29T11:30:00-05:00', '2026-09-29T11:30:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-9-p1', 'Q-9', null, 'Target integrators, attachment developers, and people who would want the dev kit.', 'thomas', '{"kind":"call","ref":"sep29-6","label":"Sep 29 call"}'::jsonb, 0, '2026-09-29T11:30:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-10', 'who-we-sell-to', null, null, 'Do local customers want a seller nearby who supports them?', 'Thomas''s hypothesis: at least some customers will want a local feel, where they get good support close by. Worth testing before it shapes the sales pages.', 'idea', 'technical', 'sales', 'Dev Kit', 'thomas', '{"kind":"call","ref":"sep29-7","label":"Sep 29 call"}'::jsonb, '2026-09-29T11:30:00-05:00', '2026-09-29T11:30:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-10-r1', 'Q-10', null, 'Especially ranchers. They want to know they can call someone, or get someone close by to help.', 'erick', '{"kind":"call","ref":"sep29-7","label":"Sep 29 call"}'::jsonb, 0, '2026-09-29T11:30:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-11', 'airframe', null, null, 'Structure and enclosure: what should the next revision change?', 'KBM asked whether there is a plan to improve the enclosure or the structure, and offered structural advice. There is no list yet. Erick is preparing easy wins for the Thursday call, and what it takes to make them. Propose each change as its own Dev Kit v1.1 improvement so it can be weighed and decided on its own; use this thread for the overall direction.', 'question', 'technical', 'structure', 'Dev Kit v1.1', 'kbm', '{"kind":"call","ref":"sep29-20","label":"Sep 29 call"}'::jsonb, '2026-09-29T11:30:00-05:00', '2026-09-29T11:30:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-12', 'config-guide', null, null, 'One large docs sync, or separate pull requests?', 'Erick has a batch of local changes to sync: configuration guide, harness, Pilot''s Handbook, SDK notes. Some flight-controller parameters deviate from the baseline on GitHub.', 'question', 'technical', 'docs', 'Dev Kit', 'erick', '{"kind":"call","ref":"sep29-18","label":"Sep 29 call"}'::jsonb, '2026-09-29T11:30:00-05:00', '2026-09-29T11:30:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-12-p1', 'Q-12', null, 'Put the flight-controller parameter changes in their own pull request so Zeynep can review and merge them. Sync the rest separately.', 'erick', '{"kind":"call","ref":"sep29-18","label":"Sep 29 call"}'::jsonb, 0, '2026-09-29T11:30:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-12-r1', 'Q-12', 'Q-12-p1', 'Okay, sounds good.', 'zeynep', '{"kind":"call","ref":"sep29-18","label":"Sep 29 call"}'::jsonb, 0, '2026-09-29T11:30:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-13', 'payload-latch', null, null, 'Latch V2: what holds the pin when power drops?', 'V1 has no spring. An unpowered servo holds the pin by friction only, and the payload rail drops on every relay cycle and reboot. It was never tested with a load. The V1 note says V2 needs a mechanical lock on power loss.', 'question', 'technical', 'payload', 'V2', null, '{"kind":"doc","ref":"payload-latch-v1","label":"Latch V1 note","url":"https://github.com/Arrow-air/payload-systems/tree/main/payloads/Payload-latch#v2-recommendations"}'::jsonb, '2026-09-17T12:00:00-05:00', '2026-09-17T12:00:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-13-p1', 'Q-13', null, 'A return spring that closes the latch when the servo lets go.', null, '{"kind":"doc","ref":"payload-latch-v1","label":"Latch V1 note","url":"https://github.com/Arrow-air/payload-systems/tree/main/payloads/Payload-latch#v2-recommendations"}'::jsonb, 0, '2026-09-17T12:00:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-13-p2', 'Q-13', null, 'Over-center pin geometry, so the load itself keeps the pin locked.', null, '{"kind":"doc","ref":"payload-latch-v1","label":"Latch V1 note","url":"https://github.com/Arrow-air/payload-systems/tree/main/payloads/Payload-latch#v2-recommendations"}'::jsonb, 1, '2026-09-17T12:00:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-14', 'payload-latch', null, null, 'Drive the latch straight from the flight controller, or add a microcontroller?', 'V1 runs the servo directly off a flight-controller PWM output, with no pulldown, so what the servo does when the signal stops has not been characterized. The V1 note says to decide from the signal-loss test.', 'question', 'technical', 'payload', 'V2', null, '{"kind":"doc","ref":"payload-latch-v1","label":"Latch V1 note","url":"https://github.com/Arrow-air/payload-systems/tree/main/payloads/Payload-latch#v2-recommendations"}'::jsonb, '2026-09-17T12:00:00-05:00', '2026-09-17T12:00:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-14-p1', 'Q-14', null, 'Keep it flight-controller PWM only.', null, '{"kind":"doc","ref":"payload-latch-v1","label":"Latch V1 note","url":"https://github.com/Arrow-air/payload-systems/tree/main/payloads/Payload-latch#v2-recommendations"}'::jsonb, 0, '2026-09-17T12:00:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-14-p2', 'Q-14', null, 'Reintroduce a microcontroller for debounce, stall guard and a lock on signal loss.', null, '{"kind":"doc","ref":"payload-latch-v1","label":"Latch V1 note","url":"https://github.com/Arrow-air/payload-systems/tree/main/payloads/Payload-latch#v2-recommendations"}'::jsonb, 1, '2026-09-17T12:00:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-15', 'multispectral', null, null, 'Camera V2: how does each image get a GPS tag?', 'On the bottom port the camera''s built-in GPS antenna faces the 2 mm aluminum lower plate, so geotags are unverified and probably missing. Without them the images are hard to use for mapping.', 'question', 'technical', 'payload', 'V2', null, '{"kind":"doc","ref":"multispectral-v1","label":"Camera V1 note","url":"https://github.com/Arrow-air/payload-systems/tree/main/payloads/Multispectral-Camera#v2-recommendations"}'::jsonb, '2026-09-17T12:00:00-05:00', '2026-09-17T12:00:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-15-p1', 'Q-15', null, 'Move it to a side port with a plain PETG GPS window, so the camera''s own antenna sees the sky.', null, '{"kind":"doc","ref":"multispectral-v1","label":"Camera V1 note","url":"https://github.com/Arrow-air/payload-systems/tree/main/payloads/Multispectral-Camera#v2-recommendations"}'::jsonb, 0, '2026-09-17T12:00:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-15-p2', 'Q-15', null, 'Feed the vehicle''s GPS (NMEA) to the camera.', null, '{"kind":"doc","ref":"multispectral-v1","label":"Camera V1 note","url":"https://github.com/Arrow-air/payload-systems/tree/main/payloads/Multispectral-Camera#v2-recommendations"}'::jsonb, 1, '2026-09-17T12:00:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-16', 'interface', null, null, 'Swapping payloads on the bottom port without rewriting parameters', 'The latch and the camera both fly on the bottom port with the same output and RC channel, but need different endpoints (1315/1750 µs against 1000/2000). Every swap means rewriting SERVO9, and a stale 1000 µs endpoint drives the latch servo past its lock stop. Both V1 notes flag it.', 'question', 'technical', 'payload', 'Dev Kit v1.1', null, '{"kind":"doc","ref":"payload-latch-v1","label":"Latch V1 note","url":"https://github.com/Arrow-air/payload-systems/tree/main/payloads/Payload-latch#v2-recommendations"}'::jsonb, '2026-09-17T12:00:00-05:00', '2026-09-17T12:00:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-16-p1', 'Q-16', null, 'A parameter file per payload, loaded when it is swapped onto the bottom port.', null, '{"kind":"doc","ref":"payload-latch-v1","label":"Latch V1 note","url":"https://github.com/Arrow-air/payload-systems/tree/main/payloads/Payload-latch#v2-recommendations"}'::jsonb, 0, '2026-09-17T12:00:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-16-p2', 'Q-16', null, 'Dedicate ports, so each payload type always lands on the same output.', null, '{"kind":"doc","ref":"payload-latch-v1","label":"Latch V1 note","url":"https://github.com/Arrow-air/payload-systems/tree/main/payloads/Payload-latch#v2-recommendations"}'::jsonb, 1, '2026-09-17T12:00:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-17', 'quiverhub', null, null, 'What should QuiverHub do next?', 'QuiverHub V1 shipped (milestones M1 to M3). The M4 and M5 named back then were never scoped, and nobody can say today what they meant. T-12 asks Alex to write the next scope after running V1 on the Houston unit (T-18), for the Project Lead to accept and the October checkpoint to fund. These are the needs T-12 lists; vote on what matters to you.', 'question', 'technical', 'software', '', null, '{"kind":"issue","ref":"258","label":"#258","url":"https://github.com/Arrow-air/project-quiver/issues/258"}'::jsonb, '2026-09-09T15:59:00-05:00', '2026-09-09T15:59:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
