insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-18', 'power', '3320', null, 'Longshot fit: does it slide into the bay and mate with the battery connector PCB?', 'Longshot was designed around Tattu geometry and uses the Tattu clip, with full-length side rail channels. But its SL board carries an ET60S-D06 connector, while Quiver''s battery connector PCB (3320) uses two Molex 46437-9206 with guide pins. No fit check against the slider (2211) or the connector PCB is recorded.', 'question', 'technical', 'battery', 'Dev Kit v1.1', null, '{"kind":"doc","ref":"pull/27","label":"LS PR #27","url":"https://github.com/Arrow-air/project-longshot/pull/27"}'::jsonb, '2026-09-30T12:00:00-05:00', '2026-09-30T12:00:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-19', 'power', null, null, 'Longshot BMS: emulate the Tattu BMS, or speak DroneCAN natively?', 'The PT1 board has no BMS: one fuse and cell-sense lines passed through to the charger. The v1 plan is an STM32 smart BMS (VESC BMS reference design) with isolated CAN. How it talks to Quiver is marked TBD in LS #26. As of the Sep 22 call there was no working BMS yet.', 'question', 'technical', 'battery', 'Dev Kit v1.1', null, '{"kind":"issue","ref":"LS-26","label":"LS #26","url":"https://github.com/Arrow-air/project-longshot/issues/26"}'::jsonb, '2026-09-30T12:00:00-05:00', '2026-09-30T12:00:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-19-p1', 'Q-19', null, 'Emulate the Tattu BMS, so Quiver''s existing battery setup and failsafes work unchanged.', null, '{"kind":"issue","ref":"LS-26","label":"LS #26","url":"https://github.com/Arrow-air/project-longshot/issues/26"}'::jsonb, 0, '2026-09-30T12:00:00-05:00') on conflict (id) do nothing;
insert into public.sa_positions (id, thread_id, parent_id, text, named, source, ord, created_at) values ('Q-19-p2', 'Q-19', null, 'Native DroneCAN battery messages.', null, '{"kind":"issue","ref":"LS-26","label":"LS #26","url":"https://github.com/Arrow-air/project-longshot/issues/26"}'::jsonb, 1, '2026-09-30T12:00:00-05:00') on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-20', 'power', null, null, 'Failsafe values for a 58.5 Ah pack', 'The values adopted in #248 (warn at 7,500 mAh left, land at 4,500, refuse to arm below 9,000) read the Tattu BMS over DroneCAN and are sized for 30 Ah. A PT1 Longshot sends no battery data, so only the voltage backstop on the ESC monitor would act. What should Quiver fly with on Longshot, before and after its BMS?', 'question', 'technical', 'battery', 'Dev Kit v1.1', null, '{"kind":"issue","ref":"248","label":"#248","url":"https://github.com/Arrow-air/project-quiver/issues/248"}'::jsonb, '2026-09-30T12:00:00-05:00', '2026-09-30T12:00:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-21', 'power', null, null, 'Charging both packs: 58.8 V for Longshot, 60.9 V for the Tattu', 'Longshot charges to 58.8 V; the Tattu LiHV pack to 60.9 V. LS #26 warns that chargers and docks must handle both cutoffs, and the Pilot''s Handbook currently calls for a 14S LiHV charger. Longshot is planned around the Tattu TA3200 plus a balance connector.', 'question', 'technical', 'battery', 'Dev Kit v1.1', null, '{"kind":"issue","ref":"LS-26","label":"LS #26","url":"https://github.com/Arrow-air/project-longshot/issues/26"}'::jsonb, '2026-09-30T12:00:00-05:00', '2026-09-30T12:00:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
insert into public.sa_threads (id, zone, part, pcb, title, body, type, kind, system, version, named, source, raised_at, active_at, settled, declined, deferrals) values ('Q-22', 'power', '3410', null, 'First Longshot test on Quiver: what does it have to show?', 'No pack-level test is recorded yet; the only data is a cell-level discharge (BAK 65E, 20.18 Wh at 10 A to 2.8 V). Before Longshot replaces the Tattu, what should a first bench test and first flight prove: fit, voltage under load, temperatures from its four sensors, endurance against the Tattu?', 'question', 'technical', 'battery', 'Dev Kit v1.1', null, '{"kind":"issue","ref":"LS-26","label":"LS #26","url":"https://github.com/Arrow-air/project-longshot/issues/26"}'::jsonb, '2026-09-30T12:00:00-05:00', '2026-09-30T12:00:00-05:00', null, null, '[]'::jsonb) on conflict (id) do nothing;
